"""==============================================================================IOTEC108_ORCHESTRATOR_ENGINE.py==============================================================================Orquestrador Central de Missões=============================================================================="""from __future__ import annotationsimport sqlite3from pathlib import Pathfrom datetime import datetimeDATABASE = Path("iotec.db")class Orchestrator:    def __init__(self):        self.conn = sqlite3.connect(DATABASE)        self.conn.row_factory = sqlite3.Row    # ======================================================================    def next_pending(self):        return self.conn.execute("""            SELECT *            FROM missions            WHERE status='PENDING'            ORDER BY id            LIMIT 1        """).fetchone()    # ======================================================================    def assign(self):        mission = self.next_pending()        if mission is None:            print("\nNenhuma missão pendente.\n")            return        mission = dict(mission)        print("=" * 70)        print("MISSÃO ENCONTRADA")        print("=" * 70)        print(f"ID..............: {mission['id']}")        print(f"MISSÃO..........: {mission['mission']}")        print(f"PRIORIDADE......: {mission['priority']}")        print(f"AGENTE..........: {mission['assigned_agent']}")        print()        self.conn.execute("""            UPDATE missions            SET                status=?,                started_at=?            WHERE id=?        """,(            "RUNNING",            datetime.utcnow().isoformat(),            mission["id"]        ))        self.conn.commit()        self.log(            mission["mission_uuid"],            mission["assigned_agent"],            "MISSION_STARTED",            "RUNNING",            "Missão iniciada pelo Orchestrator"        )        print("MISSÃO INICIADA")    # ======================================================================    def finish(self, mission_uuid):        self.conn.execute("""            UPDATE missions            SET                status=?,                finished_at=?            WHERE mission_uuid=?        """,(            "FINISHED",            datetime.utcnow().isoformat(),            mission_uuid        ))        self.conn.commit()        print("MISSÃO FINALIZADA")    # ======================================================================    def log(        self,        mission_uuid,        agent_uuid,        action,        status,        details    ):        self.conn.execute("""            INSERT INTO agent_governance(                created_at,                mission_uuid,                agent_uuid,                action,                status,                details            )            VALUES(?,?,?,?,?,?)        """,(            datetime.utcnow().isoformat(),            mission_uuid,            agent_uuid,            action,            status,            details        ))        self.conn.commit()# =============================================================================if __name__ == "__main__":    orchestrator = Orchestrator()    orchestrator.assign()